import React, { useState } from 'react';
import './Entreprise.css';
import TabNavigation from '../../components/shared/TabNavigation';
import EquipeSection from './components/EquipeSection';
import VehiculesSection from './components/VehiculesSection';
import TrajetsSection from './components/TrajetsSection';
import ContratsSection from './components/ContratsSection';
import HistoriqueSection from './components/HistoriqueSection';
import NotificationsSection from './components/NotificationsSection';

const Entreprise = () => {
  const [activeTab, setActiveTab] = useState('Tout');

  const tabs = [
    'Tout',
    'Trajets du mois',
    'Véhicules',
    'Équipe',
    'Alertes',
    'Contrats & Conventions',
    'Historique & Statistiques'
  ];

  // Fonction helper pour afficher une section
  const showSection = (sectionName) => {
    return activeTab === 'Tout' || activeTab === sectionName;
  };

  return (
    <div className="page-container">
      <h1>Entreprise</h1>

      {/* Carte générale */}
      <div className="entreprise-card">
        {/* Onglets dans la card */}
        <TabNavigation 
          tabs={tabs}
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
        />

        {/* Layout avec sections */}
        <div className="entreprise-layout">
          <div className="left-column">
            {showSection('Équipe') && <EquipeSection />}
            {showSection('Véhicules') && <VehiculesSection />}
            {showSection('Trajets du mois') && <TrajetsSection />}
          </div>

          <div className="right-column">
            {showSection('Contrats & Conventions') && <ContratsSection />}
            {showSection('Historique & Statistiques') && <HistoriqueSection />}
            {showSection('Alertes') && <NotificationsSection />}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Entreprise;
